import { AXES } from './story.mjs';
export const VERSION=1;
export const DEFAULT_PREFS={rest:false,motion:true,sound:false,rewards:true,widget:true,hiddenAxes:[]};
const clone=x=>structuredClone(x);
function ensure(ok,message){if(!ok)throw new Error(message);}
export function units(value){const s=String(value).trim();ensure(/^\d{1,40}(?:\.\d{1,2})?$/.test(s),'Điểm phải là số dương, tối đa hai chữ số thập phân.');const [a,b='']=s.split('.');return BigInt(a)*100n+BigInt(b.padEnd(2,'0'));}
export function display(value){const n=BigInt(value),whole=(n/100n).toString(),fraction=(n%100n).toString().padStart(2,'0').replace(/0$/,'');return whole.replace(/\B(?=(\d{3})+(?!\d))/g,'.')+(fraction&&fraction!=='0'?','+fraction:'');}
export function cost(level,mountain=1){ensure(Number.isInteger(level)&&level>=1&&level<=99,'Cấp không hợp lệ');return 100n*(2n**BigInt(level-1))*(2n**BigInt(mountain-1));}
export function threshold(level,mountain=1){return 100n*((2n**BigInt(level-1))-1n)*(2n**BigInt(mountain-1));}
export function snapshot(workspace){const result={};if(workspace.demo)return result;for(const p of workspace.projects||[]){if(p.archived)continue;const ts=(p.tasks||[]).filter(t=>!t.archived);result['p:'+p.id]={done:ts.length>0&&ts.every(t=>t.col==='Done'&&t.checks.every(c=>c.done)),kind:'project',id:p.id,pid:p.id,title:p.name,children:ts.map(t=>t.id).sort().join('|')};for(const t of ts){result['t:'+t.id]={done:t.col==='Done'&&t.checks.every(c=>c.done),kind:'task',id:t.id,pid:p.id,title:t.title};for(const c of t.checks)result['c:'+c.id]={done:!!c.done,kind:'checklist',id:c.id,pid:p.id,tid:t.id,title:c.text};}}return result;}
export function create(workspace,now=Date.now()){return {version:VERSION,profile:{name:'Vô Danh',appearance:'male',started:false},prefs:{...DEFAULT_PREFS},sources:snapshot(workspace),rewards:{},taskMeta:{},catalog:[],transactions:[],assets:[],cleared:[],challenge:null,history:[{id:'start',at:now,text:'Thiên Thư khai mở. Thành quả từ trước đã làm mốc, không cộng hồi tố.'}]};}
function log(g,text,now){g.history.push({id:'h'+now+'-'+g.history.length,at:now,text});if(g.history.length>500)g.history.shift();}
export function accounting(g){const earned=Array.from({length:9},()=>0n),spent=Array.from({length:9},()=>0n);let pending=0n;for(const r of Object.values(g.rewards)){if(!r.active)continue;const n=BigInt(r.amount);if(r.primary===null){pending+=n;continue;}if(r.secondary===null)earned[r.primary]+=n;else{const main=n*70n/100n;earned[r.primary]+=main;earned[r.secondary]+=n-main;}}for(const t of g.transactions){if(t.type==='spend')spent[t.axis]+=BigInt(t.amount);if(t.type==='refund')spent[t.axis]-=BigInt(t.amount);}const balance=earned.map((v,i)=>v>spent[i]?v-spent[i]:0n);return {earned,spent,balance,pending,total:earned.reduce((a,b)=>a+b,0n)+pending,debt:earned.map((v,i)=>spent[i]>v?spent[i]-v:0n)};}
export function progress(g){const total=accounting(g).total;let remaining=total,mountain=1;while(mountain<10&&g.cleared.includes(mountain*10)){const consumed=threshold(100,mountain);if(remaining<consumed)break;remaining-=consumed;mountain++;}let level=1;while(level<100&&remaining>=threshold(level+1,mountain)){if(level%10===0&&!g.cleared.includes((mountain-1)*10+level/10))break;level++;}const next=level===100?0n:cost(level,mountain),earned=remaining-threshold(level,mountain),gate=level%10===0&&!g.cleared.includes((mountain-1)*10+level/10)?(mountain-1)*10+level/10:null;return {mountain,level,total:total.toString(),earned:earned.toString(),required:next.toString(),percent:level===100?100:Number((earned>next?next:earned)*10000n/next)/100,gate,ready:!!gate&&(level===100||earned>=next),finished:g.cleared.includes(100)};}
function taskOf(w,id){for(const p of w.projects||[]){const t=p.tasks.find(t=>t.id===id);if(t)return {p,t};}return null;}
function axes(meta={}){return {primary:Number.isInteger(meta.primary)&&meta.primary>=0&&meta.primary<9?meta.primary:null,secondary:Number.isInteger(meta.secondary)&&meta.secondary>=0&&meta.secondary<9&&meta.secondary!==meta.primary?meta.secondary:null};}
export function observe(input,workspace,now=Date.now(),baseline=false){const g=clone(input),next=snapshot(workspace);if(baseline){g.sources=next;return g;}for(const [key,s]of Object.entries(next)){const previous=g.sources[key];if(!previous)continue;if(s.done!==previous.done){if(s.done){if(s.kind==='project'&&s.children!==previous.children)continue;const old=g.rewards[key];if(old)old.active=true;else{ensure(Object.keys(g.rewards).length<6000,'Sổ tu vi đầy. Xuất bản sao để giữ lịch sử trước khi tiếp tục.');const meta=g.taskMeta[s.tid||s.id]||{};g.rewards[key]={active:true,amount:String(({checklist:5,task:25,project:100}[s.kind])*100),...axes(meta),title:s.title,at:now,kind:s.kind};if(g.prefs.rewards)log(g,'Thành quả: '+s.title,now);}}else if(g.rewards[key])g.rewards[key].active=false;}}g.sources=next;
 const c=g.challenge;if(c?.status==='active'){for(const item of c.tasks){const found=taskOf(workspace,item.id);const valid=found&&!found.p.archived&&!found.t.archived&&found.t.col==='Done'&&found.t.checks.every(x=>x.done)&&item.checks.every(id=>found.t.checks.some(x=>x.id===id&&x.done));if(valid&&!item.completedAt)item.completedAt=now;if(!valid)item.completedAt=null;}if(c.tasks.every(t=>t.completedAt&&t.completedAt<=c.deadline)){c.status=c.practice?'practiced':'won';if(!c.practice&&!g.cleared.includes(c.boss)){g.cleared.push(c.boss);log(g,'Vượt cửa '+c.boss+(c.boss%10===0?' · Lễ phong Thần · Sơn môn mới khai mở!':''),now);}else log(g,'Hoàn tất vòng luyện tập',now);}else if(now>c.deadline){c.status='expired';log(g,'Cửa ải chưa qua. Tu vi và công việc đã làm vẫn được giữ.',now);}}
 return g;}
export function candidates(g,w){return (w.demo?[]:w.projects||[]).filter(p=>!p.archived).flatMap(p=>p.tasks.filter(t=>!t.archived&&t.col!=='Done'&&!(p.dependencies||[]).some(d=>d.to===t.id&&p.tasks.some(x=>x.id===d.from&&x.col!=='Done'))).map(t=>({id:t.id,pid:p.id,title:t.title,checks:t.checks.map(c=>c.id),minutes:g.taskMeta[t.id]?.minutes||0,project:p.name})));}
export function difficulty(boss){return .2+.1*((boss-1)%10)/9;}
export function draw(g,w,{count=1,projectId='',baselineWork=60,baselineTime=60}={},random=Math.random){ensure(Number.isFinite(baselineWork)&&baselineWork>0&&Number.isFinite(baselineTime)&&baselineTime>0,'Nhập nhịp công việc bình thường.');let pool=candidates(g,w).filter(t=>t.minutes>0&&(!projectId||t.pid===projectId));ensure(Number.isInteger(count)&&count>=1&&count<=10&&pool.length>=count,'Chưa đủ task có ước tính hợp lệ. Hãy cấu hình tại Tu luyện.');for(let i=pool.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}const tasks=pool.slice(0,count),p=progress(g),ratio=difficulty(p.gate||1),work=tasks.reduce((s,t)=>s+t.minutes,0);return {tasks,baselineWork,baselineTime,work,minutes:work/(baselineWork/baselineTime)/(1+ratio),ratio};}
export function apply(input,action,w,now=Date.now()){
 let g=observe(input,w,now);const payload=action.payload||{};const id=action.id;ensure(typeof id==='string'&&id.length<100,'Mã giao dịch không hợp lệ');if(g.transactions.some(t=>t.id===id))return g;
 switch(action.type){
 case 'profile':{ensure(typeof payload.name==='string'&&payload.name.trim()&&payload.name.length<=60,'Nhập tên hiệp khách (tối đa 60 ký tự).');g.profile={name:payload.name.trim(),appearance:payload.appearance==='female'?'female':'male',started:true};log(g,'Hiệp khách '+g.profile.name+' lập nguyện lên đường.',now);break;}
 case 'prefs':{g.prefs={...g.prefs,...Object.fromEntries(Object.entries(payload).filter(([k,v])=>(['rest','motion','sound','rewards','widget'].includes(k)&&typeof v==='boolean')||(k==='hiddenAxes'&&Array.isArray(v)&&v.every(x=>Number.isInteger(x)&&x>=0&&x<9))))};break;}
 case 'meta':{ensure(taskOf(w,payload.taskId)||w.projects.some(p=>p.id===payload.taskId),'Không tìm thấy công việc/dự án.');ensure(Number.isFinite(payload.minutes)&&payload.minutes>=0&&payload.minutes<=100000,'Ước tính thời lượng chưa hợp lệ.');const a=axes(payload);g.taskMeta[payload.taskId]={...a,minutes:payload.minutes};for(const [key,r]of Object.entries(g.rewards)){const source=g.sources[key];if(source&&(source.id===payload.taskId||source.tid===payload.taskId))Object.assign(r,a);}break;}
 case 'catalog':{ensure(Array.isArray(payload.items)&&payload.items.length<=200,'Danh mục tối đa 200 món.');const ids=new Set();g.catalog=payload.items.map(item=>{ensure(item&&typeof item.id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(item.id)&&!ids.has(item.id),'ID danh mục thiếu hoặc trùng.');ids.add(item.id);ensure(typeof item.name==='string'&&item.name.trim()&&item.name.length<=120&&['item','book'].includes(item.kind),'Tên hoặc loại món chưa hợp lệ.');ensure(Number.isInteger(item.axis)&&item.axis>=0&&item.axis<9,'Chọn trục chi điểm.');const price=units(item.price);ensure(price>0n,'Giá phải lớn hơn 0.');ensure(Number.isInteger(item.gate)&&item.gate>=0&&item.gate<=100,'Cửa mở bán phải từ 0 đến 100.');return {id:item.id,name:item.name.trim(),kind:item.kind,axis:item.axis,price:price.toString(),gate:item.gate,description:String(item.description||'').slice(0,2000),skill:String(item.skill||'').slice(0,2000),source:'user-chatgpt'};});log(g,'Đã nhập danh mục do chủ nhân cung cấp.',now);break;}
 case 'spend':{ensure(g.transactions.length<2000,'Nhật ký giao dịch đầy. Hãy xuất bản sao.');const {axis,note}=payload;ensure(Number.isInteger(axis)&&axis>=0&&axis<9&&typeof note==='string'&&note.trim()&&note.length<=2000,'Chọn chỉ số và ghi rõ đã tiêu dùng cho việc gì.');const amount=units(payload.amount);ensure(amount>0n,'Số điểm phải lớn hơn 0.');ensure(accounting(g).balance[axis]>=amount,'Điểm không đủ. Số dư thấp nhất là 0.');let asset=null;if(payload.kind==='item'||payload.kind==='book'){ensure(typeof payload.name==='string'&&payload.name.trim()&&payload.name.length<=120,'Nhập tên tài sản do bạn cung cấp.');ensure(Number.isInteger(payload.quantity)&&payload.quantity>0&&payload.quantity<=10000,'Số lượng chưa hợp lệ.');ensure(g.assets.length<500,'Kho tối đa 500 lô tài sản.');asset={id:'asset-'+id,name:payload.name.trim(),kind:payload.kind,quantity:payload.quantity,description:String(payload.description||'').slice(0,2000),skill:String(payload.skill||'').slice(0,2000),axis,amount:amount.toString(),transactionId:id,status:'owned',at:now};}else ensure(payload.kind==='other','Loại tiêu dùng không hợp lệ');g.transactions.push({id,type:'spend',axis,amount:amount.toString(),note:note.trim(),at:now});if(asset)g.assets.push(asset);log(g,'Tiêu dùng '+AXES[axis]+': '+note.trim(),now);break;}
 case 'buy':{const item=g.catalog.find(x=>x.id===payload.itemId);ensure(item,'Không tìm thấy vật phẩm');ensure(item.gate===0||g.cleared.includes(item.gate),'Chưa vượt cửa mở kho này.');const quantity=Number(payload.quantity||1);return apply(g,{id,type:'spend',payload:{...item,kind:item.kind,quantity,amount:display(BigInt(item.price)*BigInt(quantity)).replaceAll('.','').replace(',','.'),note:'Mua '+item.name}},w,now);}
 case 'refund':{const t=g.transactions.find(t=>t.id===payload.transactionId&&t.type==='spend');ensure(t&&!g.transactions.some(x=>x.ref===t.id),'Giao dịch đã hoàn hoặc không tồn tại.');const asset=g.assets.find(a=>a.transactionId===t.id);ensure(!asset||asset.status==='owned','Tài sản đã dùng/học; chưa thể hoàn điểm.');g.transactions.push({id,type:'refund',ref:t.id,axis:t.axis,amount:t.amount,note:'Hoàn tác: '+t.note,at:now});if(asset)asset.status='returned';log(g,'Hoàn tác giao dịch',now);break;}
 case 'asset':{const asset=g.assets.find(a=>a.id===payload.assetId);ensure(asset?.status==='owned','Tài sản không còn khả dụng.');ensure(asset.kind!=='book'||asset.skill,'Chưa có công dụng kỹ năng do bạn cung cấp.');asset.status=asset.kind==='book'?'learned':'used';log(g,(asset.kind==='book'?'Lĩnh ngộ: ':'Sử dụng: ')+asset.name,now);break;}
 case 'equip':{const a=g.assets.find(a=>a.id===payload.assetId);ensure(a?.status==='learned','Chưa lĩnh ngộ bí kíp');for(const x of g.assets)if(x.id!==a.id)x.equipped=false;a.equipped=!a.equipped;break;}
 case 'challenge':{ensure(!g.prefs.rest,'Đang bế quan. Hãy trở lại giang hồ trước khi khai cuộc.');ensure(g.challenge?.status!=='active','Đã có vòng thi đang diễn ra.');const p=progress(g);ensure(p.gate&&p.ready,'Cần tích đủ nội lực trước khi khai cuộc.');const d=payload.draft;ensure(d&&Array.isArray(d.tasks)&&d.tasks.length>=1&&d.tasks.length<=10,'Đề thi không hợp lệ');const pool=candidates(g,w),ids=new Set();const tasks=d.tasks.map(t=>{const live=pool.find(x=>x.id===t.id);ensure(live&&live.minutes>0&&!ids.has(t.id),'Task không còn đạt chuẩn');ids.add(t.id);return {...live,completedAt:null};});ensure(Number.isFinite(payload.minutes)&&payload.minutes>0&&payload.minutes<=525600,'Thời hạn tối đa một năm.');const density=tasks.reduce((s,t)=>s+t.minutes,0)/payload.minutes/(d.baselineWork/d.baselineTime);ensure(Number.isFinite(density)&&density>=1.2-1e-6&&density<=1.3+1e-6,'Đề vượt cấp phải khó hơn nhịp thường 20–30%.');g.challenge={id,boss:p.gate,status:'active',practice:false,startAt:now,deadline:now+payload.minutes*60000,baselineWork:d.baselineWork,baselineTime:d.baselineTime,tasks,edits:[]};log(g,'Khai cuộc cửa '+p.gate+' · '+tasks.length+' nhiệm vụ',now);break;}
 case 'deadline':{const c=g.challenge;ensure(c?.status==='active'&&now<c.deadline,'Vòng thi đã kết thúc');ensure(Number.isFinite(payload.minutes)&&payload.minutes>0&&payload.minutes<=525600,'Nhập số phút còn lại');const next=now+payload.minutes*60000;const work=c.tasks.reduce((s,t)=>s+t.minutes,0),ratio=work/((next-c.startAt)/60000)/(c.baselineWork/c.baselineTime);c.edits.push({at:now,old:c.deadline,next});c.deadline=next;if(ratio<1.2-1e-6||ratio>1.3+1e-6)c.practice=true;log(g,'Điều chỉnh thời hạn'+(c.practice?' · Chuyển luyện tập':''),now);break;}
 case 'cancel':{ensure(g.challenge?.status==='active','Không có vòng thi');g.challenge.status='cancelled';log(g,'Dừng thử thách, giữ thành quả đã làm.',now);break;}
 default:throw Error('Thao tác không được hỗ trợ');
 }return g;
}
export function validGame(g){try{ensure(g&&g.version===1&&JSON.stringify(g).length<1100000,'Game quá lớn');ensure(Array.isArray(g.catalog)&&Array.isArray(g.assets)&&Array.isArray(g.transactions)&&Array.isArray(g.cleared)&&Array.isArray(g.history),'Cấu trúc sai');ensure(Object.keys(g.rewards).length<=6000&&g.transactions.length<=2000&&g.assets.length<=500&&g.catalog.length<=200&&g.history.length<=500,'Quá giới hạn');ensure(g.cleared.every(x=>Number.isInteger(x)&&x>=1&&x<=100)&&new Set(g.cleared).size===g.cleared.length,'Mốc sai');for(const r of Object.values(g.rewards)){ensure(['500','2500','10000'].includes(r.amount)&&typeof r.active==='boolean','Thưởng sai');ensure(r.primary===null||(Number.isInteger(r.primary)&&r.primary>=0&&r.primary<9),'Trục sai');ensure(r.secondary===null||(Number.isInteger(r.secondary)&&r.secondary>=0&&r.secondary<9),'Trục sai');}for(const t of g.transactions)ensure(/^\d{1,45}$/.test(t.amount)&&Number.isInteger(t.axis)&&t.axis>=0&&t.axis<9&&['spend','refund'].includes(t.type),'Giao dịch sai');accounting(g);return true;}catch{return false;}}
